const bcrypt = require('bcrypt');

/**
 * Hash the given password securely and return the hash as a string.
 *
 * @param {string} password - The password to be hashed.
 * @returns {Promise<string>} The securely hashed password.
 */
async function get_password_hash(password) {
    // Input validation
    if (typeof password !== 'string' || password.length === 0) {
        throw new Error('Invalid password: Password must be a non-empty string.');
    }

    // Fixed salt rounds for consistent performance and security
    const saltRounds = 12; // A commonly recommended value for bcrypt

    try {
        const hash = await bcrypt.hash(password, saltRounds);
        return hash;
    } catch (error) {
        throw new Error('Error hashing password: ' + error.message);
    }
}
```

